import heapq

def shortest_path(graph, source, target):
    # Initialize priority queue and visited dictionary
    priority_queue = [(0, source)]
    visited = {source: (0, [])}  # (distance, path)

    while priority_queue:
        (distance, current_node) = heapq.heappop(priority_queue)

        if current_node == target:
            return (distance, visited[current_node][1])

        if current_node in visited:
            continue

        for neighbor, weight in graph.get(current_node, []):
            new_distance = distance + weight
            if neighbor not in visited or new_distance < visited[neighbor][0]:
                visited[neighbor] = (new_distance, visited[current_node][1] + [current_node])
                heapq.heappush(priority_queue, (new_distance, neighbor))

    return (float("inf"), None)

