def shortest_path(graph, source, target):
    # Initialize the distance and previous node dictionaries 
    distance = {node: float('inf') for node in graph}
    distance[source] = 0
    previous = {node: None for node in graph}

    # Function to calculate the shortest path using Dijkstra's algorithm
    def dijkstra(graph, source):
        unvisited = set(graph.keys())
        while unvisited:
            # Find the node with the smallest distance
            current = min(unvisited, key=lambda node: distance[node])
            if distance[current] == float('inf'):
                break
            unvisited.remove(current)

            # Update the distances of the neighbors
            for neighbor, weight in graph[current]:
                if distance[current] + weight < distance[neighbor]:
                    distance[neighbor] = distance[current] + weight
                    previous[neighbor] = current
        return previous

    # Run Dijkstra's algorithm
    previous = dijkstra(graph, source)

    # If the target is not reachable, return infinity and None
    if previous[target] is None:
        return (float('inf'), None)

    # Reconstruct the path
    path = []
    current = target
    while current is not None:
        path.insert(0, current)
        current = previous[current]
    return (distance[target], path)

