def shortest_path(graph, source, target):
    # Priority queue to store (distance, node) pairs
    from heapq import heappush, heappop
    from collections import defaultdict

    # Initialize the priority queue
    queue = [(0, [source])]
    # Initialize a dictionary to store the shortest distance to each node
    shortest_distance = {source: 0}

    while queue:
        current_distance, current_path = heappop(queue)
        # If we reached the target node, return the path
        if current_path[-1] == target:
            return (current_distance, current_path)
        # If we have already found a shorter path to this node, skip it
        if current_distance > shortest_distance.get(current_path[-1], float('inf')):
            continue
        for neighbor, weight in graph.get(current_path[-1], []):
            new_distance = current_distance + weight
            new_path = current_path + [neighbor]
            # If we found a shorter path to the neighbor
            if new_distance < shortest_distance.get(neighbor, float('inf')):
                shortest_distance[neighbor] = new_distance
                heappush(queue, (new_distance, new_path))

    # If we couldn't find a path to the target node
