def shortest_path(graph, source, target):
    from collections import deque

    def bfs(graph, source):
        distances = {vertex: float('inf') for vertex in graph}
        distances[source] = 0
        queue = deque([source])

        while queue:
            current_vertex = queue.popleft()

            for neighbor, weight in graph.get(current_vertex, []):
                distance = distances[current_vertex] + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    queue.append(neighbor)

        return distances[target] if distances[target] != float('inf') else float('inf')

    shortest_distance = bfs(graph, source)
    if shortest_distance == float('inf'):
        return float('inf'), None
    else:
        path = []
        vertex = target
        while vertex != source:
            for neighbor, weight in graph.get(vertex, []):
                if distances[vertex] == distances[neighbor] + weight:
                    path.append(neighbor)
                    vertex = neighbor
                    break
        path.append(source)
        path.reverse()
        return shortest_distance, path
