    import heapq

    def dijkstra(graph, start):
        # Priority queue for the Dijkstra algorithm
        queue = [(0, start)]
        # Dictionary to store the shortest distance to each node
        distances = {node: float('inf') for node in graph}
        distances[start] = 0
        # Dictionary to store the path
        previous_nodes = {node: None for node in graph}
        # Dictionary to store the shortest path from start to each node
        shortest_paths = {node: float('inf') for node in graph}
        shortest_paths[start] = [start]

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_distance > distances[current_node]:
                continue

            for neighbour, weight in graph.get(current_node, []):
                distance = current_distance + weight

                if distance < distances[neighbour]:
                    distances[neighbour] = distance
                    previous_nodes[neighbour] = current_node
                    shortest_paths[neighbour] = shortest_paths[current_node] + [neighbour]
                    heapq.heappush(queue, (distance, neighbour))

        return distances, previous_nodes, shortest_paths

    distances, previous_nodes, shortest_paths = dijkstra(graph, source)
    if shortest_paths[target] is None:
        return float('inf'), None
    else:
        return distances[target], shortest_paths[target]
