from collections import deque

def shortest_path(graph, source, target):
    # If the target is in the graph, otherwise it's already unreachable
    if target in graph:
        # Initialize the distance to source as 0 and to other nodes as infinity
        distance = {node: float('inf') for node in graph}
        distance[source] = 0
        # Initialize the parent dictionary to keep track of the path
        parent = {source: None}
        # Queue for BFS
        queue = deque([source])

        while queue:
            current = queue.popleft()
            # Check all neighbors of the current node
            for neighbor, weight in graph.get(current, []):
                # Calculate the new distance to the neighbor through the current node
                distance_to_neighbor = distance[current] + weight
                if distance_to_neighbor < distance[neighbor]:
                    distance[neighbor] = distance_to_neighbor
                    parent[neighbor] = current
                    # Add the neighbor to the queue for further exploration
                    queue.append(neighbor)

        # If target is reached, construct the path
        if distance[target] != float('inf'):
            path = []
            current = target
            while current:
                path.append(current)
                current = parent.get(current)
            return (distance[target], path[::-1])
        else:
            return (float('inf'), None)
    else:
        return (float('inf'), None)

