def shortest_path(graph, source, target):
    import heapq

    def dijkstra(graph, start, end):
        # Using a dictionary to keep track of the smallest distance to each node
        distance = {node: float('inf') for node in graph}
        distance[start] = 0
        # Using a priority queue to ensure we always expand the least costly node first
        priority_queue = [(0, start)]

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            # If we have already found a better path to the current node, skip it
            if current_distance > distance[current_node]:
                continue

            # Explore all neighbors
            for neighbor, weight in graph.get(current_node, []):
                distance_to_neighbor = current_distance + weight

                # If we found a shorter path to the neighbor
                if distance_to_neighbor < distance[neighbor]:
                    distance[neighbor] = distance_to_neighbor
                    heapq.heappush(priority_queue, (distance_to_neighbor, neighbor))

        # If the target is not reachable, distance[target] will be infinity
        if distance[end] == float('inf'):
            return float('inf'), []

        # Reconstruct the path
        path = []
        current_node = end
        while current_node != start:
            path.append(current_node)
            for neighbor, _ in graph.get(current_node, []):
                if distance[current_node] == distance[neighbor] + 1:
                    current_node = current_node
                    break
                if distance[current_node] == distance[neighbor]:
                    current_node = neighbor
                    break
            else:
                current_node = start
        path.append(start)
        path.reverse()
        return distance[end], path

    return dijkstra(graph, source, target)

